<?php

declare(strict_types=1);

namespace StripeSDK\DTOs\Mandate;

/**
 * mandate_paypal
 */
final class Paypal extends \Dmorenof\SdkRuntime\DTO
{
    protected const array VALIDATION = [
        'billing_agreement_id' => [
            'maxLength' => 5000,
        ],
        'payer_id' => [
            'maxLength' => 5000,
        ],
    ];

    /**
     * The PayPal Billing Agreement ID (BAID). This is an ID generated by PayPal which represents the mandate between the merchant and the customer.
     */
    public ?string $billing_agreement_id {
        set {
            $this->assigning('billing_agreement_id', $value);
            $this->billing_agreement_id = $value;
        }
    }
    /**
     * PayPal account PayerID. This identifier uniquely identifies the PayPal customer.
     */
    public ?string $payer_id {
        set {
            $this->assigning('payer_id', $value);
            $this->payer_id = $value;
        }
    }

    protected function assignMember(string $name, mixed $value): void
    {
        match ($name) {
            'billing_agreement_id' => $value === null || is_string($value) ? $this->billing_agreement_id = $value : parent::assignMember($name, $value),
            'payer_id' => $value === null || is_string($value) ? $this->payer_id = $value : parent::assignMember($name, $value),
            default => parent::assignMember($name, $value),
        };
    }
}
